import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { PLAY_DESCRIPTIONS } from "../packages/plays/src/descriptions.ts";

const path = fileURLToPath(new URL("../docs/plays.md", import.meta.url));
const guide = `# Choosing a play

<!-- Generated by scripts/generate-play-guide.ts. The intro lives in that script; each play's text in packages/plays/src/descriptions.ts. -->

Pick the play by what happened to the buyer, not by what you sell. Each one below says when it fits, what it does, what it needs and what it produces.

Preview every draft before it goes. Email and LinkedIn send when you send; X, Reddit and Hacker News drafts are posted by you, then marked sent. The dashboard shows each play's cadence timing and its optional letter. To carry an unanswered email cadence on to LinkedIn, see [LinkedIn](./linkedin.md#continuing-an-email-cadence-on-linkedin).

${Object.entries(PLAY_DESCRIPTIONS)
  .map(
    ([name, d]) =>
      `## ${name}\n\n- **When to use it:** ${d.whenToUse}\n- **What it does:** ${d.actions}\n- **What you need:** ${d.requires}\n- **What it produces:** ${d.produces}\n`,
  )
  .join("\n")}`;
if (process.argv.includes("--check")) {
  if (readFileSync(path, "utf8") !== guide) {
    console.error("Play guide is stale. Run bun run scripts/generate-play-guide.ts");
    process.exitCode = 1;
  }
} else writeFileSync(path, guide);
